'use strict';
// Optional daily comfort rule. A single map period drives every weather metric.
class AirQuality {
 constructor(){
  this.root=document.getElementById('air-quality');this.toggle=document.getElementById('aq-enabled');this.maximumInput=document.getElementById('aq-max');this.content=document.getElementById('aq-content');this.status=document.getElementById('aq-status');this.results=document.getElementById('aq-results');this.retry=document.getElementById('aq-retry');this.enabled=false;this.maximum=100;this.id=0;this.location=null;
  const q=new URLSearchParams(location.search);this.toggle.checked=q.get('aqi')==='1';this.maximumInput.value=[50,100,150,200,300,500].includes(Number(q.get('aqmax')))?q.get('aqmax'):'100';this.maximumInput.disabled=!this.toggle.checked;
  this.toggle.addEventListener('change',()=>{this.maximumInput.disabled=!this.toggle.checked;this.previewPeriod();window.ComfyDays?.ui.refresh();});this.maximumInput.addEventListener('change',()=>window.ComfyDays?.ui.refresh());
  document.getElementById('aq-settings').onclick=()=>{window.ComfyDays.ui.open('weather');this.toggle.focus({preventScroll:true});};this.retry.onclick=()=>this.refresh();
 }
 get pending(){return this.toggle.checked!==this.enabled||this.toggle.checked&&Number(this.maximumInput.value)!==this.maximum;}
 apply(p){this.enabled=Boolean(p.aqenabled);this.maximum=p.aqmax;this.toggle.checked=this.enabled;this.maximumInput.value=String(this.maximum);this.maximumInput.disabled=!this.enabled;this.refresh();}
 reset(){this.apply({aqenabled:false,aqmax:100});}
 appendURL(q){if(this.enabled){q.set('aqi','1');q.set('aqmax',this.maximum);}}
 previewPeriod(){const period=this.appliedPeriod,label=period==='recent'?'2023–2025':period==='mean'?'2020–2025':period||'selected';document.getElementById('aq-period-note').textContent=this.toggle.checked&&['mean','2020','2021','2022'].includes(period)?'Apply will switch all weather metrics to 2023–2025.':`Uses the map period: ${label}. AQI supports 2023–2025.`;}
 syncPeriod(period){const changed=period!==this.appliedPeriod;this.appliedPeriod=period;const label=period==='recent'?'2023–2025':period==='mean'?'2020–2025':period;document.getElementById('aq-period-note').textContent=`Uses the map period: ${label}. AQI supports 2023–2025.`;const select=document.getElementById('period');for(const o of select.options)o.disabled=this.enabled&&['mean','2020','2021','2022'].includes(o.value);this.previewPeriod();if(changed)this.refresh();}
 select(node,lat,lon){const key=[node,lat,lon].join('|');if(this.key===key)return;this.key=key;this.location={node,lat,lon};document.getElementById('aq-place').textContent=`Climate cell · ${lat.toFixed(2)}°, ${lon.toFixed(2)}°`;this.refresh();}
 clear(message){this.location=null;this.key='';document.getElementById('aq-place').textContent=message||'Select a city or click the map.';this.refresh();if(message)this.status.textContent='AQI history is unavailable for this location.';}
 description(){return `Daily AQI ≤${this.maximum} · maximum 3-hour mean · −1 point per 50 above limit`;}
 async refresh(){
  const id=++this.id;this.controller?.abort();this.controller=new AbortController();this.root.setAttribute('aria-busy','false');this.content.hidden=false;document.getElementById('aq-off').hidden=this.enabled;this.results.replaceChildren();this.results.hidden=true;this.retry.hidden=true;
  if(!['recent','2023','2024','2025'].includes(this.appliedPeriod)){this.status.textContent='AQI history is available for 2023–2025. Choose a supported period to see the chart.';return;}
  if(!this.location||this.location.node<0){this.status.textContent='Select a location to inspect the daily AQI used in its comfort calculation.';return;}
  this.status.textContent='Loading daily AQI for this climate cell…';this.root.setAttribute('aria-busy','true');
  try{const url=new URL('api/aqi/daily/v1',location.href);url.searchParams.set('node',this.location.node);url.searchParams.set('months',window.ComfyDays?.state?.monthMask||4095);url.searchParams.set('period',this.appliedPeriod);url.searchParams.set('max',this.maximum);const r=await fetch(url,{signal:AbortSignal.any([this.controller.signal,AbortSignal.timeout(45000)])});if(!r.ok)throw Error('Daily AQI unavailable');const d=await r.json();if(id!==this.id)return;if(d.version!==1||d.period!==this.appliedPeriod||d.limit!==this.maximum||!Number.isInteger(d.count)||d.count<0||d.count>d.calendar||!Array.isArray(d.months)||d.months.length!==12)throw Error('Invalid daily AQI summary');this.render(d);
  }catch(e){if(id!==this.id||e.name==='AbortError')return;this.status.textContent='AQI could not load. Missing AQI adds no penalty and does not exclude this location.';this.retry.hidden=false;}
  finally{if(id===this.id)this.root.setAttribute('aria-busy','false');}
 }
 renderChart(d){
  const mask=window.ComfyDays?.state?.monthMask||4095,available=d.months.filter((m,i)=>(mask&(1<<i))&&m.mean!==null&&Number.isFinite(m.mean));
  if(!available.length){const p=document.createElement('p');p.className='aq-empty';p.textContent='No monthly AQI values are available for this location and period.';this.results.append(p);return;}
  const section=document.createElement('section');section.className='aq-chart';const heading=document.createElement('h3');heading.textContent='Air quality through the year';const intro=document.createElement('p');intro.textContent='Monthly average of the daily maximum 3-hour AQI. The dashed line marks the AQI reference limit; a monthly average does not show how many individual days exceeded it.';section.append(heading,intro);
  const wrap=document.createElement('div');wrap.className='aq-chart-scroll';wrap.tabIndex=0;wrap.setAttribute('role','region');wrap.setAttribute('aria-label','Monthly air quality chart');const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 720 240');svg.setAttribute('role','img');svg.setAttribute('aria-label','Monthly average daily AQI. Exact values and coverage are in the monthly table.');
  const add=(tag,attrs,text)=>{const e=document.createElementNS(ns,tag);for(const [key,value] of Object.entries(attrs))e.setAttribute(key,value);if(text!==undefined)e.textContent=text;svg.append(e);return e;}, labels=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'], left=50,top=18,width=650,height=175,max=Math.max(this.maximum,...available.map(m=>m.mean),1)*1.15,x=i=>left+(i+.5)*width/12,y=v=>top+height*(1-v/max);
  for(let i=0;i<=4;i++){const value=max*i/4;add('line',{x1:left,y1:y(value),x2:left+width,y2:y(value),class:'aq-grid'});add('text',{x:left-8,y:y(value)+4,'text-anchor':'end',class:'aq-axis'},String(Math.round(value)));}
  add('line',{x1:left,y1:y(this.maximum),x2:left+width,y2:y(this.maximum),class:'aq-limit'});let previous=null;const readout=document.createElement('p');readout.className='aq-readout';readout.textContent=`Daily limit: ${this.maximum} AQI · Select a point to inspect.`;
  d.months.forEach((m,i)=>{if(!(mask&(1<<i))){previous=null;return;}add('text',{x:x(i),y:top+height+24,'text-anchor':'middle',class:'aq-axis'},labels[i]);if(m.mean===null||!Number.isFinite(m.mean)){previous=null;return;}if(previous)add('line',{x1:previous[0],y1:previous[1],x2:x(i),y2:y(m.mean),class:'aq-line'});previous=[x(i),y(m.mean)];const label=`${labels[i]}: ${Number(m.mean).toLocaleString('en',{maximumFractionDigits:1})} AQI, ${m.count} of ${m.calendar} days with data`;const point=add('circle',{cx:x(i),cy:y(m.mean),r:5,class:'aq-point',tabindex:'0','aria-label':label});const title=document.createElementNS(ns,'title');title.textContent=label;point.append(title);point.addEventListener('focus',()=>readout.textContent=label);point.addEventListener('pointerenter',()=>readout.textContent=label);});wrap.append(svg);section.append(wrap,readout);this.results.append(section);
 }
 render(d){
  const el=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e;},fmt=v=>v===null?'Not available':Number(v).toLocaleString('en',{maximumFractionDigits:1});
  this.status.textContent=`${d.count} / ${d.calendar} days with AQI. ${d.calendar-d.count} days without AQI: no penalty; air quality not verified.`;
  const stats=el('dl');stats.className='aq-stats';for(const [label,value]of [[this.enabled?'Days within your AQI limit':`Days with AQI ≤${this.maximum}`,`${d.within} / ${d.count}`],['Mean of daily maximum 3-hour AQI',fmt(d.mean)]]){const row=el('div');row.append(el('dt',label),el('dd',value));stats.append(row);}this.results.append(stats);this.renderChart(d);this.results.append(el('p','AQI-only counts. A Comfy Day must also meet your temperature, rain and optional sunshine rules.'));
  const details=el('details'),scroll=el('div'),table=el('table'),head=el('thead'),tr=el('tr');details.append(el('summary','View monthly AQI'));scroll.className='aq-table-scroll';scroll.tabIndex=0;scroll.setAttribute('role','region');scroll.setAttribute('aria-label','Monthly daily AQI table');table.append(el('caption','UTC days · daily maximum of complete 3-hour means · at least 22 valid hourly values'));
  for(const text of ['Month','Mean daily AQI','Days ≤ your limit','Days with AQI','Calendar days']){const th=el('th',text);th.scope='col';tr.append(th);}head.append(tr);table.append(head);const body=el('tbody');d.months.forEach((m,i)=>{if(!((window.ComfyDays?.state?.monthMask||4095)&(1<<i)))return;const row=el('tr');for(const text of [['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][i],fmt(m.mean),m.within,m.count,m.calendar])row.append(el('td',String(text)));body.append(row);});table.append(body);scroll.append(table);details.append(scroll);this.results.append(details);this.results.hidden=false;
 }
}
window.AirQuality=AirQuality;
